const BY_ID: Record<string, GlossaryEntry> = Object.fromEntries(GLOSSARY.map((g) => [g.id, g]));

/** Glossary lookup; undefined for an unknown id. */
export function glossaryEntry(id: string): GlossaryEntry | undefined {
  return BY_ID[id];
}
